    {
        var loyaltyCents = LoyaltyDiscountPolicy.PartCents(subtotalCents, tier);
        var promoCents = PromoCodePolicy.PartCents(promoCode, subtotalCents - loyaltyCents);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }
}
